-- # Lernfeld 5: Cyberphysische Systeme > ## Datengrundlagen > - Zahlensysteme

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann eine Zahl im Binärsystem mehr Stellen benötigen als im Dezimalsystem, um denselben Wert darzustellen?', 2, '[{"text": "Ja", "correct": true, "because": "Binär verwendet nur 0 und 1, daher mehr Stellen"}, {"text": "Nein", "correct": false, "because": "Binär ist weniger kompakt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Hexadezimalsystem allein durch seine Basis 16 immer effizienter als das Dezimalsystem?', 2, '[{"text": "Nein", "correct": true, "because": "Effizienz hängt von Anwendung ab"}, {"text": "Ja", "correct": false, "because": "Basis allein entscheidet nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Können negative Zahlen im Binärsystem ohne zusätzliche Codierung wie Zweierkomplement dargestellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Binär hat kein natives Vorzeichen"}, {"text": "Ja", "correct": false, "because": "Vorzeichen braucht Codierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist jede Zahl im Oktalsystem auch direkt im Hexadezimalsystem darstellbar?', 2, '[{"text": "Ja", "correct": true, "because": "Beide sind ganzzahlig und umfassen alle Werte"}, {"text": "Nein", "correct": false, "because": "Werte sind kompatibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Dezimalsystem ohne Rundung alle Werte des Binärsystems exakt wiedergeben?', 2, '[{"text": "Nein", "correct": true, "because": "Binäre Brüche wie 0.1 sind im Dezimalsystem unendlich"}, {"text": "Ja", "correct": false, "because": "Rundungsfehler treten auf"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Zahlensystem verwendet die Basis 8?', 2, '[{"text": "Oktalsystem", "correct": true, "because": "Basis 8 definiert Oktal"}, {"text": "Hexadezimalsystem", "correct": false, "because": "Basis 16"}, {"text": "Binärsystem", "correct": false, "because": "Basis 2"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Darstellung entspricht der Binärzahl 1010 im Dezimalsystem?', 3, '[{"text": "10", "correct": true, "because": "1*2^3 + 0*2^2 + 1*2^1 + 0*2^0 = 10"}, {"text": "12", "correct": false, "because": "Falsche Berechnung"}, {"text": "5", "correct": false, "because": "Missverständnis der Stellenwerte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Zahlensystem wird primär in der Computertechnik für Speicheradressen verwendet?', 2, '[{"text": "Hexadezimalsystem", "correct": true, "because": "Kompakt und binärnah"}, {"text": "Dezimalsystem", "correct": false, "because": "Weniger praktisch"}, {"text": "Oktalsystem", "correct": false, "because": "Seltener genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die hexadezimale Entsprechung der Dezimalzahl 255?', 2, '[{"text": "FF", "correct": true, "because": "15*16^1 + 15*16^0 = 255"}, {"text": "FE", "correct": false, "because": "254, nicht 255"}, {"text": "100", "correct": false, "because": "256, falscher Wert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Zahlensystem erfordert die wenigsten Zeichen, um den Wert 100 darzustellen?', 2, '[{"text": "Hexadezimalsystem", "correct": true, "because": "64h = 100d, 2 Zeichen"}, {"text": "Dezimalsystem", "correct": false, "because": "100, 3 Zeichen"}, {"text": "Binärsystem", "correct": false, "because": "1100100, 7 Zeichen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Zahlensysteme sind direkt mit der Basis 2 kompatibel?', 4, '[{"text": "Binärsystem", "correct": true, "because": "Basis 2"}, {"text": "Oktalsystem", "correct": true, "because": "Basis 8 = 2^3"}, {"text": "Dezimalsystem", "correct": false, "because": "Basis 10"}, {"text": "Hexadezimalsystem", "correct": true, "because": "Basis 16 = 2^4"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen das Hexadezimalsystem in der Programmierung nützlich?', 3, '[{"text": "Kürzere Darstellung", "correct": true, "because": "Kompakter als Binär"}, {"text": "Direkte Binärumrechnung", "correct": true, "because": "4 Bits pro Zeichen"}, {"text": "Einfache Addition", "correct": false, "because": "Nicht einfacher als Dezimal"}, {"text": "Lesbarkeit für Menschen", "correct": true, "because": "Kürzer als Binär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte könnten im Oktalsystem als ungültig angesehen werden?', 3, '[{"text": "8", "correct": true, "because": "Oktal geht bis 7"}, {"text": "5", "correct": false, "because": "Gültig in Basis 8"}, {"text": "9", "correct": true, "because": "Über Basis 8 hinaus"}, {"text": "0", "correct": false, "because": "Gültig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zahlensysteme könnten irrtümlich als identisch wahrgenommen werden?', 4, '[{"text": "Binär und Oktal", "correct": true, "because": "Beide potenzbasiert"}, {"text": "Dezimal und Hexadezimal", "correct": true, "because": "Ähnliche Ziffern"}, {"text": "Oktal und Hexadezimal", "correct": true, "because": "Beide kompakter als Binär"}, {"text": "Binär und Dezimal", "correct": false, "because": "Zu unterschiedlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen treten bei der Umrechnung zwischen Zahlensystemen auf?', 3, '[{"text": "Rundungsfehler bei Brüchen", "correct": true, "because": "Binär-Dezimal ungenau"}, {"text": "Verlust von Vorzeichen", "correct": true, "because": "Ohne Codierung unklar"}, {"text": "Eindeutige Darstellung", "correct": false, "because": "Meist eindeutig"}, {"text": "Komplexität bei großen Zahlen", "correct": true, "because": "Rechenaufwand steigt"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Binärsystem ist das einzige System mit Basis 2. b) Hexadezimalzahlen sind immer kürzer als ihre dezimalen Entsprechungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Binär ist Basis 2, Hex nicht immer kürzer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Im Oktalsystem gibt es keine Ziffern über 7. b) Das Dezimalsystem ist für Computer effizienter als Binär.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oktal bis 7, Binär ist effizienter"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Binärzahl kann ohne Verlust in Hexadezimal umgewandelt werden. b) Das Oktalsystem ist für Speicheradressen besser geeignet als Hexadezimal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Binär-Hex verlustfrei, Hex ist bevorzugt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Das Zweierkomplement ist nur im Binärsystem anwendbar. b) Dezimalzahlen können immer exakt in Binär umgerechnet werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zweierkomplement binärspezifisch, Dezimal-Binär ungenau"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Hexadezimal ist eine direkte Erweiterung des Oktalsystems. b) Binärzahlen sind für Menschen schwerer lesbar als Dezimalzahlen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Hex nicht Oktal-basiert, Binär weniger lesbar"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

